sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float levels;
uniform float offset;
uniform float style;

half4 main(float2 coord) {
    half4 col = image.eval(coord);
    if (col.a < 1e-3) return half4(0);
    float3 rgb = float3(col.rgb / col.a);
    float n = style > 0.5 ? levels : max(levels, 1.0);
    if (style > 0.5 && levels <= 0.0) return half4(0.0, 0.0, 0.0, col.a);
    float o = style > 0.5 ? offset + 0.0075 * n + 0.057 : offset;
    float3 q = clamp((floor(rgb * n + o) - o) / n, 0.0, 1.0);
    return half4(half3(q) * col.a, col.a);
}
